def stations(rows):
    out = []
    for sid, t, s, bg, x, y, crit in rows:
        d = {"id": sid, "t": t, "s": s, "bg": bg, "x": x, "y": y}
        if crit is not None:
            d["crit"] = crit
        out.append(d)
    return out


