def l01_parts(L):
    """يحوّل بيانات «اللهُ رَبّي» إلى أجزاء المحرّك (كما هي، بلا تغيير في المحتوى)."""
    o, r, c, b, st = L["observe"], L["reflect"], L["command"], L["blessings"], L["stamp"]
    P = {
        "observe": [{"p": "reveal", "head": o["head"], "cards": o["cards"]},
                    dict(p="mcq", **o["q"]), {"p": "concl", "html": o["concl"]}],
        "reflect": [{"p": "inst", "ic": "🔎", "text": r["head"]}, {"p": "imgs", "imgs": r["imgs"]},
                    {"p": "list", "items": r["qs"]}] + [dict(p="mcq", **q) for q in r["mcq"]]
                   + [{"p": "concl", "html": r["concl"]}],
        "command": [{"p": "reveal", "head": c["head"], "cards": c["cards"]}, dict(p="mcq", **c["q"]),
                    dict(p="cmap", **L["cmap"])],
        "blessings": [{"p": "reveal", "head": b["head"], "cards": b["cards"]},
                      {"p": "share", "head": b["shareHead"], "lines": b["share"]},
                      {"p": "record", "title": "أُعَبِّرُ بِصَوْتي عَنْ حُبّي لِرَبّي وَشُكْري لَهُ.", "hint": "أَقْرَأُ الْجُمْلَتَيْنِ بِصَوْتٍ واضِحٍ."},
                      {"p": "ayah", "head": b["ayahHead"], "lines": [b["ayah"]], "ref": b["ayahRef"], "note": b["ayahNote"]}],
        "letters": [{"p": "order", "small": 1, "head": L["letters"]["head"] + "، أَلْمِسُها بِالتَّرْتيبِ.", "list": L["letters"]["list"]},
                    {"p": "build", "items": [["اللهُ", "مَنْ رَبُّ الْعالَمينَ؟", "🌍"], ["الْغَيْثَ", "الْمَطَرُ", "🌧️"], ["الْقانِطينَ", "الْيائِسينَ مِنْ رَحْمَةِ اللهِ", "🤲"]]}],
        "stamp": [{"p": "color", "head": st["colorHead"], "words": st["colorWords"]},
                  dict(p="pick", **st["a2"]), dict(p="pick", **st["a3"]),
                  {"p": "pledge", "head": st["head"], "pledges": st["pledges"]}],
    }
    for s in L["stations"]:
        if s["id"] in P:
            s["parts"] = P[s["id"]]
    for k in ("observe", "reflect", "command", "cmap", "blessings", "letters", "stamp"):
        L.pop(k)


