def st(rows):
    """rows: (id, t, s, bg, crit, parts) — المواقع على الخريطة من STATIONS_10."""
    out = []
    for (sid, t, s, bg, crit, parts), base in zip(rows, STATIONS_10):
        d = {"id": sid, "t": t, "s": s, "bg": bg, "x": base[4], "y": base[5]}
        if crit is not None:
            d["crit"] = crit
        if parts:
            d["parts"] = parts
        out.append(d)
    return out


