def _ensure_check():
    """كل رحلة تنتهي بمحطة «أتحقّق» (الاختبار الأخير والتقييم الذاتي بعد الرحلة والخاتمة).
    إن نقصت أُضيفت محطة أخيرة، وضُغطت مواقع الخريطة رأسيًّا لتتّسع لها."""
    for L in LESSONS.values():
        S = L["stations"]
        if any(s["id"] == "check" for s in S):
            continue
        for s in S:
            s["y"] = round(6 + (s["y"] - 6) * 0.9, 1)
        last = S[-1]
        S.append({"id": "check", "t": "أَتَحَقَّقُ", "s": "الْقِنْديلُ الْأَخيرُ", "bg": "#FFF6E3",
                  "x": 30 if last["x"] > 50 else 70, "y": round(last["y"] + 8.5, 1)})


_ensure_check()
